	if tc.subpath == "" {
		args = append(args, "--subpath", ".changes")
	}
	args = append(args, "entries")
	out, err := modGen.With(daggerCallAt(".", args...)).Stdout(ctx)
	require.NoError(t, err)

	require.Contains(t, out, "v0.9.1.md")
	require.NotContains(t, out, "v0.9.2.md")
})

