			supportsMembers bool
			source          string
		}
		for _, tc := range []testCase{
			{
				sdk:             "go",
				fixture:         "go/type-custom-enum-type-01",
				supportsMembers: true,
				source: `package main

// Enum for Status
type Status string

const (
	// Active status
	Active Status = "ACTIVE value"

	// Inactive status
	Inactive Status = "INACTIVE value"

	// Weird status
	WEIRD Status = "WEIRD"
)

func New(
	// +default="INACTIVE value"
	status Status,
) *Test {
	return &Test{Status: status}
}

type Test struct {
	Status Status
}

func (m *Test) FromStatus(status Status) string {
	return string(status)
}

func (m *Test) FromStatusOpt(
	// +optional
	status Status,
) string {
	return string(status)
}

func (m *Test) ToStatus(status string) Status {
	return Status(status)
}
`,
			},
			{
				sdk:             "python",
				fixture:         "python/type-custom-enum-type-02",
				supportsMembers: true,
				source: `import enum

import dagger

@dagger.enum_type
class Status(enum.Enum):
    """Enum for Status"""

    ACTIVE = "ACTIVE value"
    """Active status"""

    INACTIVE = "INACTIVE value"
    """Inactive status"""

    WEIRD = "WEIRD"
    """Weird status"""


@dagger.object_type
class Test:
    status: Status = dagger.field(default=Status.INACTIVE)

    @dagger.function
    def from_status(self, status: Status) -> str:
        return status.value

    @dagger.function
    def from_status_opt(self, status: Status | None) -> str:
        return status.value if status else ""

    @dagger.function
    def to_status(self, status: str) -> Status:
        # Doing "Status(status)" will fail in Python, so mock
        # it to force sending the invalid value back to the server.
        class MockEnum(enum.Enum):
            ACTIVE = "ACTIVE value"
            INACTIVE = "INACTIVE value"
            INVALID = "INVALID"

        return MockEnum(status)
`,
			},
			{
				sdk:             "typescript",
				fixture:         "typescript/type-custom-enum-type-03",
				supportsMembers: true,
				source: `import { func, object } from "@dagger.io/dagger"

/**
 * Enum for Status
 */
export enum Status {
  /**
   * Active status
   */
  Active = "ACTIVE value",

  /**
   * Inactive status
   */
  Inactive = "INACTIVE value",

  /**
   * Weird status
   */
  WEIRD = "WEIRD",
}

@object()
export class Test {
  @func()
  status: Status

  constructor(status: Status = Status.Inactive) {
    this.status = status
  }

  @func()
  fromStatus(status: Status): string {
    return status as string
  }

  @func()
  fromStatusOpt(status?: Status): string {
	if (status) {
		return status as string
	}
    return ""
  }

  @func()
  toStatus(status: string): Status {
    return status as Status
  }
}
`,
			},
		} {
			t.Run(tc.sdk, func(ctx context.Context, t *testctx.T) {
				c := connect(ctx, t)
				modGen := moduleFixture(t, c, tc.fixture)

				out, err := modGen.With(daggerQuery(`{status}`)).Stdout(ctx)
				require.NoError(t, err)
				require.Equal(t, "INACTIVE", gjson.Get(out, "status").String())

				out, err = modGen.With(daggerQuery(`{fromStatus(status: ACTIVE)}`)).Stdout(ctx)
				require.NoError(t, err)
				if tc.supportsMembers {
					require.Equal(t, "ACTIVE value", gjson.Get(out, "fromStatus").String())
				} else {
					require.Equal(t, "ACTIVE", gjson.Get(out, "fromStatus").String())
				}

				out, err = modGen.With(daggerQuery(`{fromStatus(status: INACTIVE)}`)).Stdout(ctx)
				require.NoError(t, err)
				if tc.supportsMembers {
					require.Equal(t, "INACTIVE value", gjson.Get(out, "fromStatus").String())
				} else {
					require.Equal(t, "INACTIVE", gjson.Get(out, "fromStatus").String())
				}

				_, err = modGen.With(daggerQuery(`{fromStatus(status: "INVALID")}`)).Stdout(ctx)
				requireErrOut(t, err, "invalid enum")

				out, err = modGen.With(daggerQuery(`{fromStatusOpt}`)).Stdout(ctx)
				require.NoError(t, err)
				require.Equal(t, "", gjson.Get(out, "fromStatusOpt").String())

				out, err = modGen.With(daggerQuery(`{fromStatusOpt(status: ACTIVE)}`)).Stdout(ctx)
				require.NoError(t, err)
				if tc.supportsMembers {
					require.Equal(t, "ACTIVE value", gjson.Get(out, "fromStatusOpt").String())
				} else {
					require.Equal(t, "ACTIVE", gjson.Get(out, "fromStatusOpt").String())
				}

				_, err = modGen.With(daggerQuery(`{fromStatusOpt(status: "INVALID")}`)).Stdout(ctx)
				requireErrOut(t, err, "invalid enum")

				if tc.supportsMembers {
					out, err = modGen.With(daggerQuery(`{toStatus(status: "INACTIVE value")}`)).Stdout(ctx)
				} else {
					out, err = modGen.With(daggerQuery(`{toStatus(status: "INACTIVE")}`)).Stdout(ctx)
				}
				require.NoError(t, err)
				require.Equal(t, "INACTIVE", gjson.Get(out, "toStatus").String())

