			mainSha, err := modGen.WithExec([]string{"git", "rev-parse", "HEAD"}).Stdout(ctx)
			require.NoError(t, err)
			require.Regexp(t, `^[a-f0-9]{40}$`, strings.TrimSpace(mainSha))
