			require.Equal(t, "ref: refs/heads/master", strings.TrimSpace(out))
			out, err = modGen.With(daggerCallAt(".", "fn-ref", "--ref", ".git#ye-olde", "file", "--path=.git/HEAD", "contents")).Stdout(ctx)
