			require.NoError(t, err)
			require.Equal(t, "ref: refs/heads/main", strings.TrimSpace(out))

			out, err = modGen.With(daggerCallAt(".", "fn-ref", "--ref", remote, "file", "--path=.git/HEAD", "contents")).Stdout(ctx)
			require.NoError(t, err)
