			require.NoError(t, err)
			require.Equal(t, "foo", out)

			out, err = modGen.With(daggerCallAt(".", "fn", "--file", "file://../otherdir/foo.txt", "contents")).Stdout(ctx)
			require.NoError(t, err)
			require.Equal(t, "foo", out)

