		require.Equal(t, "build ran", strings.TrimSpace(out))

		out, err = ctr.With(moduleLoadingDaggerCallFail("run")).CombinedOutput(ctx)
		require.NoError(t, err)
		require.Contains(t, out, "run")
	})
}

