			CombinedOutput(ctx)
		require.NoError(t, err)
		require.Contains(t, out, `local module dep source path ".." escapes context "/work"`)
	})

	t.Run("local dependency source cannot be absolute", func(ctx context.Context, t *testctx.T) {
