func (TypeSuite) TestCustomEnumType(ctx context.Context, t *testctx.T) {
	t.Run("custom enum type", func(ctx context.Context, t *testctx.T) {
		type testCase struct {
			sdk             string
			fixture         string
			supportsMembers bool
			source          string
		}
		for _, tc := range []testCase{
			{
				sdk:             "go",
				fixture:         "go/type-custom-enum-type-01",
				supportsMembers: true,
				source: `package main

// Enum for Status
type Status string

const (
	// Active status
	Active Status = "ACTIVE value"

	// Inactive status
	Inactive Status = "INACTIVE value"

	// Weird status
	WEIRD Status = "WEIRD"
)

func New(
	// +default="INACTIVE value"
	status Status,
) *Test {
	return &Test{Status: status}
}

type Test struct {
	Status Status
}

func (m *Test) FromStatus(status Status) string {
	return string(status)
}

func (m *Test) FromStatusOpt(
	// +optional
	status Status,
) string {
	return string(status)
}

func (m *Test) ToStatus(status string) Status {
	return Status(status)
}
`,
			},
			{
				sdk:             "python",
				fixture:         "python/type-custom-enum-type-02",
				supportsMembers: true,
				source: `import enum

import dagger

@dagger.enum_type
class Status(enum.Enum):
    """Enum for Status"""

    ACTIVE = "ACTIVE value"
    """Active status"""

    INACTIVE = "INACTIVE value"
    """Inactive status"""

    WEIRD = "WEIRD"
    """Weird status"""


@dagger.object_type
class Test:
    status: Status = dagger.field(default=Status.INACTIVE)

    @dagger.function
    def from_status(self, status: Status) -> str:
        return status.value

    @dagger.function
    def from_status_opt(self, status: Status | None) -> str:
        return status.value if status else ""

    @dagger.function
    def to_status(self, status: str) -> Status:
        # Doing "Status(status)" will fail in Python, so mock
        # it to force sending the invalid value back to the server.
        class MockEnum(enum.Enum):
            ACTIVE = "ACTIVE value"
            INACTIVE = "INACTIVE value"
            INVALID = "INVALID"

        return MockEnum(status)
`,
			},
			{
				sdk:             "typescript",
				fixture:         "typescript/type-custom-enum-type-03",
				supportsMembers: true,
				source: `import { func, object } from "@dagger.io/dagger"

/**
 * Enum for Status
 */
export enum Status {
  /**
   * Active status
   */
  Active = "ACTIVE value",

  /**
   * Inactive status
   */
  Inactive = "INACTIVE value",

  /**
   * Weird status
   */
  WEIRD = "WEIRD",
}

@object()
export class Test {
  @func()
  status: Status

  constructor(status: Status = Status.Inactive) {
    this.status = status
  }

  @func()
  fromStatus(status: Status): string {
    return status as string
  }

  @func()
  fromStatusOpt(status?: Status): string {
	if (status) {
		return status as string
	}
    return ""
  }

  @func()
  toStatus(status: string): Status {
    return status as Status
  }
}
`,
			},
		} {
			t.Run(tc.sdk, func(ctx context.Context, t *testctx.T) {
				c := connect(ctx, t)
				modGen := moduleFixture(t, c, tc.fixture)

				out, err := modGen.With(daggerQuery(`{status}`)).Stdout(ctx)
