t.Run("keep class prototype inside module", func(ctx context.Context, t *testctx.T) {
	c := connect(ctx, t)

	modGen := c.Container().From(golangImage).
		WithMountedFile(testCLIBinPath, daggerCliFile(t, c)).
		WithWorkdir("/work").
		With(withModuleFixture(t, c, ".", "typescript/base-test")).
		With(sdkSource("typescript", `
import { func, object } from "@dagger.io/dagger"

@object()
export class Test {
  @func()
  test() {
    return new PModule(new PCheck(4))
  }
}

@object()
export class PCheck {
  @func()
  value: number

  constructor(value: number) {
    this.value = value
  }

  get doubled() {
    return this.value * 2
  }
}

@object()
export class PModule {
  @func()
  value: PCheck

  constructor(value: PCheck) {
    this.value = value
  }
  @func()
  print() {
    return this.value.doubled ?? 0
  }
}
`))

	out, err := modGen.With(daggerCallAt(".", "test", "print")).Stdout(ctx)
	require.NoError(t, err)
	require.Equal(t, "8", out)
})

