	"encoding/json"

	"dagger/coolsdk/internal/dagger"
)

type Coolsdk struct {}

func (m *Coolsdk) ModuleTypes(ctx context.Context, modSource *dagger.ModuleSource, introspectionJSON *dagger.File, outputFilePath string) (*dagger.Container, error) {
