			require.NoError(t, tc.writeFiles(modDir))

			c := connect(ctx, t)

			res, err := testutil.QueryWithClient[Resp](c, t, introspect, &testutil.QueryOptions{
				Variables: map[string]any{"path": modDir},
			})
