	for _, tc := range useLocalDepTestCases {
		t.Run(fmt.Sprintf("%s parent calls local dependency", tc.sdk), func(ctx context.Context, t *testctx.T) {
			c := connect(ctx, t)
			modGen := testModuleWithLocalDep(t, c, tc.fixture)

