func (TypeSuite) TestArgOwnType(ctx context.Context, t *testctx.T) {

	type testCase struct {
		sdk     string
		fixture string
		source  string
	}
	for _, tc := range []testCase{
		{
			sdk:     "go",
			fixture: "go/type-arg-own-type-01",
			source: `package main

import "strings"

type Test struct{}

type Message struct {
	Content string
}

func (m *Test) SayHello(name string) Message {
	return Message{Content: "hello " + name}
}

func (m *Test) Upper(msg Message) Message {
	msg.Content = strings.ToUpper(msg.Content)
	return msg
}

func (m *Test) Uppers(msg []Message) []Message {
	for i := range msg {
		msg[i].Content = strings.ToUpper(msg[i].Content)
	}
	return msg
}`,
		},
		{
			sdk:     "python",
			fixture: "python/type-arg-own-type-02",
			source: `import dagger

@dagger.object_type
class Message:
    content: str = dagger.field()

@dagger.object_type
class Test:
    @dagger.function
    def say_hello(self, name: str) -> Message:
        return Message(content=f"hello {name}")

    @dagger.function
    def upper(self, msg: Message) -> Message:
        msg.content = msg.content.upper()
        return msg

    @dagger.function
    def uppers(self, msg: list[Message]) -> list[Message]:
        for m in msg:
            m.content = m.content.upper()
        return msg
`,
		},
		{
			sdk:     "typescript",
			fixture: "typescript/type-arg-own-type-03",
			source: `
import { object, func } from "@dagger.io/dagger"

@object()
export class Message {
  @func()
  content: string

  constructor(content: string) {
    this.content = content
  }
}

@object()
export class Test {
  @func()
  sayHello(name: string): Message {
    return new Message("hello " + name)
  }

  @func()
  upper(msg: Message): Message {
    msg.content = msg.content.toUpperCase()
    return msg
  }

  @func()
  uppers(msg: Message[]): Message[] {
    for (let i = 0; i < msg.length; i++) {
      msg[i].content = msg[i].content.toUpperCase()
    }
    return msg
  }
}
`,
		},
	} {
		t.Run(tc.sdk, func(ctx context.Context, t *testctx.T) {
			c := connect(ctx, t)

			modGen := moduleFixture(t, c, tc.fixture)

			out, err := modGen.With(daggerQuery(`{sayHello(name: "world"){id}}`)).Stdout(ctx)
			require.NoError(t, err)
			id := gjson.Get(out, "sayHello.id").String()

			out, err = modGen.With(daggerQuery(`{upper(msg:"%s"){content}}`, id)).Stdout(ctx)
			require.NoError(t, err)
			require.JSONEq(t, `{"upper":{"content": "HELLO WORLD"}}`, out)

			out, err = modGen.With(daggerQuery(`{uppers(msg:["%s", "%s"]){content}}`, id, id)).Stdout(ctx)
			require.NoError(t, err)
			require.JSONEq(t, `{"uppers":[{"content": "HELLO WORLD"}, {"content": "HELLO WORLD"}]}`, out)
		})
	}
}

