    ACTIVE = "ACTIVE value"
    """Active status"""

    INACTIVE = "INACTIVE value"
    """Inactive status"""

    WEIRD = "WEIRD"
    """Weird status"""


@dagger.object_type
class Test:
    status: Status = dagger.field(default=Status.INACTIVE)

    @dagger.function
    def from_status(self, status: Status) -> str:
