func (TypeSuite) TestScalarType(ctx context.Context, t *testctx.T) {
	type testCase struct {
		sdk     string
		fixture string
		source  string
	}
	for _, tc := range []testCase{
		{
			sdk:     "go",
			fixture: "go/type-scalar-type-01",
			source: `package main

import "dagger/test/internal/dagger"

type Test struct{}

func (m *Test) FromPlatform(platform dagger.Platform) string {
	return string(platform)
}

func (m *Test) ToPlatform(platform string) dagger.Platform {
	return dagger.Platform(platform)
}

func (m *Test) FromPlatforms(platform []dagger.Platform) []string {
	result := []string{}
	for _, p := range platform {
		result = append(result, string(p))
	}
	return result
}

func (m *Test) ToPlatforms(platform []string) []dagger.Platform {
	result := []dagger.Platform{}
	for _, p := range platform {
		result = append(result, dagger.Platform(p))
	}
	return result
}
`,
		},
		{
			sdk:     "python",
			fixture: "python/type-scalar-type-02",
			source: `import dagger
from dagger import function, object_type

@object_type
class Test:
    @function
    def from_platform(self, platform: dagger.Platform) -> str:
        return str(platform)

    @function
    def to_platform(self, platform: str) -> dagger.Platform:
        return dagger.Platform(platform)

    @function
    def from_platforms(self, platform: list[dagger.Platform]) -> list[str]:
        return [str(p) for p in platform]

    @function
    def to_platforms(self, platform: list[str]) -> list[dagger.Platform]:
        return [dagger.Platform(p) for p in platform]
`,
		},
		{
			sdk:     "typescript",
			fixture: "typescript/type-scalar-type-03",
			source: `import { object, func, Platform } from "@dagger.io/dagger"

@object()
export class Test {
	@func()
	fromPlatform(platform: Platform): string {
		return platform as string
	}

	@func()
	toPlatform(platform: string): Platform {
		return platform as Platform
	}

	@func()
	fromPlatforms(platform: Platform[]): string[] {
		return platform.map(p => p as string)
	}

	@func()
	toPlatforms(platform: string[]): Platform[] {
		return platform.map(p => p as Platform)
	}
}
`,
		},
	} {
		t.Run(tc.sdk, func(ctx context.Context, t *testctx.T) {
			c := connect(ctx, t)
			modGen := moduleFixture(t, c, tc.fixture)

			out, err := modGen.With(daggerQuery(`{fromPlatform(platform: "linux/amd64")}`)).Stdout(ctx)
			require.NoError(t, err)
			require.Equal(t, "linux/amd64", gjson.Get(out, "fromPlatform").String())
			_, err = modGen.With(daggerQuery(`{fromPlatform(platform: "invalid")}`)).Stdout(ctx)
			requireErrOut(t, err, "unknown operating system or architecture")

			out, err = modGen.With(daggerQuery(`{toPlatform(platform: "linux/amd64")}`)).Stdout(ctx)
			require.NoError(t, err)
			require.Equal(t, "linux/amd64", gjson.Get(out, "toPlatform").String())
			_, err = modGen.With(daggerQuery(`{toPlatform(platform: "invalid")}`)).Sync(ctx)
			requireErrOut(t, err, "unknown operating system or architecture")

			out, err = modGen.With(daggerQuery(`{fromPlatforms(platform: ["linux/amd64"])}`)).Stdout(ctx)
			require.NoError(t, err)
			require.Equal(t, 1, len(gjson.Get(out, "fromPlatforms").Array()))
			require.Equal(t, "linux/amd64", gjson.Get(out, "fromPlatforms.0").String())
			_, err = modGen.With(daggerQuery(`{fromPlatforms(platform: ["invalid"])}`)).Stdout(ctx)
			requireErrOut(t, err, "unknown operating system or architecture")

			out, err = modGen.With(daggerQuery(`{toPlatforms(platform: ["linux/amd64"])}`)).Stdout(ctx)
			require.NoError(t, err)
			require.Equal(t, 1, len(gjson.Get(out, "toPlatforms.0").Array()))
			require.Equal(t, "linux/amd64", gjson.Get(out, "toPlatforms.0").String())
			_, err = modGen.With(daggerQuery(`{toPlatforms(platform: ["invalid"])}`)).Sync(ctx)
			requireErrOut(t, err, "unknown operating system or architecture")
		})
	}
}

// TestModuleSdkHelpHeuristic exercises the rule that decides between
// "show wrapper help" and "dispatch to the SDK". The decision is based
// on whether any positional (non-dash-prefixed) argument is present,
// because DisableFlagParsing forwards parent persistent flags into
// the arg list and we shouldn't make decisions based on that noise.
func TestModuleSdkHelpHeuristic(t *testing.T) {
	for _, tt := range []struct {
		name         string
		args         []string
		wantDispatch bool
	}{
		{"no args → help", nil, false},
		{"only --help → help", []string{"--help"}, false},
		{"only -h → help", []string{"-h"}, false},
		{"persistent flag only → help", []string{"--load-module=foo"}, false},
		{"persistent flag and --help → help", []string{"--x-release=", "--help"}, false},
		{"subcommand only → dispatch", []string{"python-version"}, true},
		{"subcommand with arg → dispatch", []string{"python-version", "3.13"}, true},
		{"subcommand with --help → dispatch", []string{"python-version", "--help"}, true},
		{"flag then subcommand → dispatch", []string{"--load-module=foo", "go-mod-tidy"}, true},
	} {
		t.Run(tt.name, func(t *testing.T) {
			hasSubcommand := false
			for _, a := range tt.args {
				if len(a) > 0 && a[0] != '-' {
					hasSubcommand = true
					break
				}
			}
			require.Equal(t, tt.wantDispatch, hasSubcommand)
		})
	}
}

