		wantRemote string
	}{
		{
			urlStr: "ssh://git@github.com/shykes/daggerverse",
			want: &gitutil.GitURL{
				Scheme:   "ssh",
				User:     url.User("git"),
				Host:     "github.com",
				Path:     "/shykes/daggerverse",
				Fragment: nil,
			},
			wantRemote: "ssh://git@github.com/shykes/daggerverse",
